import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Collections;

public class Cutting {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            sb.append(line).append(' ');
        }
        String[] tokens = sb.toString().trim().split("\\s+");
        int pos = 0;
        int n = Integer.parseInt(tokens[pos++]);
        int b = Integer.parseInt(tokens[pos++]);
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(tokens[pos++]);
        }

        int[] balance = new int[n];
        balance[0] = (a[0] % 2 == 0) ? 1 : -1;
        for (int i = 1; i < n; i++) {
            balance[i] = balance[i - 1] + ((a[i] % 2 == 0) ? 1 : -1);
        }

        ArrayList<Integer> costs = new ArrayList<Integer>();
        for (int i = 0; i < n - 1; i++) {
            if (balance[i] == 0) {
                costs.add(Math.abs(a[i] - a[i + 1]));
            }
        }
        Collections.sort(costs);
        int used = 0;
        int maxCuts = 0;
        for (int i = 0; i < costs.size(); i++) {
            int cost = costs.get(i);
            if (used + cost <= b) {
                used += cost;
                maxCuts++;
            } else {
                break;
            }
        }
        System.out.println(maxCuts);
    }
}
